INSERT INTO announcement_text (announcement_id, locale, title, body) VALUES
('019a5000-0002-7000-8000-000000000001', 'th', 'ปิดปรับปรุงระบบลงทะเบียน', 'ระบบลงทะเบียนเรียนจะปิดปรับปรุงวันเสาร์ที่ 8 พ.ย. เวลา 22:00–24:00 น. ช่วงนี้จะลงทะเบียนหรือดูผลการเรียนไม่ได้'),
('019a5000-0002-7000-8000-000000000002', 'th', 'เปิดรับสมัครทุนการศึกษาภาคเรียนที่ 2', 'ยื่นใบสมัครได้ที่กองกิจการนักศึกษาหรือทางอีเมลภายในวันที่ 20 พ.ย. 2569 รายละเอียดคุณสมบัติอยู่ในเว็บไซต์คณะ'),
('019a5000-0002-7000-8000-000000000003', 'th', 'ตรวจสุขภาพประจำปีชั้นปีที่ 1', 'นักศึกษาชั้นปีที่ 1 ตรวจสุขภาพได้ที่ศูนย์การแพทย์ อาคาร 3 ชั้น 2 วันที่ 12–14 พ.ย. เวลา 08:30–15:30 น. งดอาหารก่อนตรวจ 8 ชั่วโมง'),
('019a5000-0002-7000-8000-000000000004', 'th', 'ห้องสมุดขยายเวลาช่วงสอบ', 'ตั้งแต่ 17 พ.ย. ถึง 5 ธ.ค. ห้องสมุดเปิดถึง 24:00 น. ทุกวัน แสดงบัตรนักศึกษาเมื่อเข้าหลัง 20:00 น.'),
('019a5000-0002-7000-8000-000000000005', 'th', 'ซ้อมอพยพหนีไฟ อาคารคลินิก', 'วันพุธที่ 19 พ.ย. เวลา 10:00 น. มีการซ้อมอพยพหนีไฟที่อาคารคลินิก เมื่อได้ยินสัญญาณให้เดินตามป้ายทางออกไปยังจุดรวมพลหน้าอาคาร');
